/** Pin the browser release to the exact three curated payloads. Never modifies source data. */
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
const root = new URL("../", import.meta.url);
const entries = await Promise.all(
  ["meta", "products", "listings"].map(async (name) => {
    const bytes = await readFile(new URL(`static/app/${name}.json`, root));
    return [
      name,
      {
        sha256: createHash("sha256").update(bytes).digest("hex"),
        bytes: bytes.length,
      },
    ];
  }),
);
const output =
  "/** Generated by dev/stamp-read-model.mjs. Exact payload identity for this browser release. */\nexport const readModelManifest = " +
  JSON.stringify(Object.fromEntries(entries), null, 2) +
  ";\n";
const target = new URL("src/lib/read-model-manifest.js", root);
let previous;
try {
  previous = await readFile(target, "utf8");
} catch {}
if (previous !== output) await writeFile(target, output, "utf8");
console.log("Read-model identity stamped for meta, products and listings.");
